<?php
session_start();
require_once __DIR__ . '/../includes/config.php';

if (!isset($conn) || !($conn instanceof mysqli)) die('Database connection is not available.');

$is_admin = !empty($_SESSION['admin_logged_in']);
if (!$is_admin && !empty($_SESSION['user_id'])) {
    $stmt = $conn->prepare("SELECT role, full_name, email FROM users WHERE id=? LIMIT 1");
    if ($stmt) {
        $uid=(int)$_SESSION['user_id']; $stmt->bind_param('i',$uid); $stmt->execute();
        $u=$stmt->get_result()->fetch_assoc(); $stmt->close();
        if ($u && strtolower((string)($u['role']??''))==='admin') {
            $is_admin=true; $_SESSION['admin_logged_in']=true; $_SESSION['admin_name']=$u['full_name']??'Administrator'; $_SESSION['admin_email']=$u['email']??'';
        }
    }
}
if (!$is_admin) { header('Location: ../admin-login.php'); exit; }

function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$message=''; $message_type='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $id=(int)($_POST['rider_id']??0); $action=trim($_POST['action']??'');
    $map=['approve'=>'active','reject'=>'inactive','block'=>'blocked','activate'=>'active'];
    if($id>0 && isset($map[$action])){
        $status=$map[$action]; $stmt=$conn->prepare("UPDATE riders SET status=? WHERE id=? LIMIT 1");
        if($stmt){$stmt->bind_param('si',$status,$id);$message_type=$stmt->execute()?'success':'error';$message=$stmt->execute()?'Rider status updated successfully.':'Unable to update rider status: '.$stmt->error;$stmt->close();}
        else{$message='Database error: '.$conn->error;$message_type='error';}
    } else {$message='Invalid rider management request.';$message_type='error';}
}

$status_filter=strtolower(trim($_GET['status']??'all')); $allowed=['all','pending','active','inactive','blocked']; if(!in_array($status_filter,$allowed,true))$status_filter='all';
$search=trim($_GET['search']??'');
$total=$pending=$active=$inactive=$blocked=0;
$q=$conn->query("SELECT COUNT(*) total,SUM(status='pending') pending,SUM(status='active') active,SUM(status='inactive') inactive,SUM(status='blocked') blocked FROM riders");
if($q){$c=$q->fetch_assoc();$total=(int)($c['total']??0);$pending=(int)($c['pending']??0);$active=(int)($c['active']??0);$inactive=(int)($c['inactive']??0);$blocked=(int)($c['blocked']??0);}

$riders=[];$sql="SELECT id,full_name,email,phone,cnic,vehicle_type,bike_number,address,status,created_at FROM riders";$where=[];$params=[];$types='';
if($status_filter!=='all'){$where[]='status=?';$params[]=$status_filter;$types.='s';}
if($search!==''){$where[]='(full_name LIKE ? OR email LIKE ? OR phone LIKE ? OR cnic LIKE ? OR bike_number LIKE ?)';$s='%'.$search.'%';for($i=0;$i<5;$i++)$params[]=$s;$types.='sssss';}
if($where)$sql.=' WHERE '.implode(' AND ',$where);
$sql.=" ORDER BY CASE status WHEN 'pending' THEN 1 WHEN 'active' THEN 2 WHEN 'inactive' THEN 3 WHEN 'blocked' THEN 4 ELSE 5 END, created_at DESC";
$stmt=$conn->prepare($sql);if($stmt){if($params)$stmt->bind_param($types,...$params);$stmt->execute();$res=$stmt->get_result();while($row=$res->fetch_assoc())$riders[]=$row;$stmt->close();}
$adminName=$_SESSION['admin_name']??'Humsafar Administrator';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Riders | Humsafar Admin</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>
*{box-sizing:border-box}body{margin:0;font-family:"Segoe UI",Arial,sans-serif;background:#fff8fb;color:#292929}.main{margin-left:218px;width:calc(100% - 218px);padding:16px 28px 35px}.topbar{min-height:60px;background:#fff;border:1px solid #f0e4e9;padding:10px 14px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.topbar h1{margin:0;font-size:25px;font-weight:900}.topbar p{margin:4px 0 0;color:#999;font-size:10px}.date{border:1px solid #f1ccd9;border-radius:9px;padding:9px 12px;color:#df0038;font-size:10px;font-weight:800}.message{padding:12px 14px;border-radius:9px;margin-bottom:16px;font-size:11px;font-weight:700}.success{color:#177245;background:#e7f8ed;border:1px solid #c6ecd5}.error{color:#b42318;background:#fff0ee;border:1px solid #f2c7c1}.banner{border-radius:17px;padding:22px 24px;color:#fff;background:linear-gradient(110deg,#ee003d,#f34882);display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.banner h2{margin:0 0 6px;font-size:20px}.banner p{margin:0;font-size:10px;opacity:.9}.banner-icon{width:55px;height:55px;border-radius:15px;background:#ffffff2e;display:flex;align-items:center;justify-content:center;font-size:25px}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:11px;margin-bottom:18px}.stat{min-height:105px;padding:14px 10px;border-radius:13px;background:#fff;border:1px solid #f1dfe7;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.stat strong{display:block;margin-top:7px;font-size:20px}.stat span{margin-top:4px;color:#777;font-size:9px}.card{background:#fff;border:1px solid #f1dfe7;border-radius:15px;overflow:hidden}.card-head{padding:16px 18px;border-bottom:1px solid #f3e4ea;display:flex;align-items:center;gap:10px}.card-head h3{margin:0;font-size:15px}.card-head p{margin:3px 0 0;color:#999;font-size:9px}.filter{padding:15px;background:#fffafd;border-bottom:1px solid #f3e4ea}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.search{flex:1;min-width:260px;position:relative}.search i{position:absolute;left:13px;top:50%;transform:translateY(-50%);color:#ef003c;font-size:12px}.search input,.select{width:100%;height:42px;padding:0 12px;border:1px solid #ead4df;border-radius:9px;background:#fff;outline:0;font-size:10px}.search input{padding-left:38px}.select{width:auto;min-width:145px;font-weight:700}.btn{height:42px;padding:0 15px;border:0;border-radius:9px;background:#ef003c;color:#fff;cursor:pointer;font-size:10px;font-weight:800}.reset{display:inline-flex;align-items:center;height:42px;padding:0 14px;border:1px solid #ef003c;border-radius:9px;color:#ef003c;background:#fff;font-size:10px;font-weight:800;text-decoration:none}.table-wrap{overflow:auto}table{width:100%;min-width:1050px;border-collapse:collapse}thead{background:#fff6fa}th{padding:13px 12px;text-align:left;color:#777;font-size:8px;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid #f2e2e8}td{padding:13px 12px;border-bottom:1px solid #f5e8ed;font-size:9px;vertical-align:middle}.rider{display:flex;align-items:center;gap:9px}.avatar{width:36px;height:36px;border-radius:10px;background:#ef003c;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:900}.name{font-weight:800}.muted{color:#999;font-size:8px;margin-top:3px}.pill{display:inline-block;padding:5px 9px;border-radius:20px;font-size:8px;font-weight:800}.active-pill{background:#e8f8ef;color:#16834a}.pending-pill{background:#fff0d8;color:#a65b00}.inactive-pill{background:#f2f2f2;color:#666}.blocked-pill{background:#ffe8ec;color:#c00032}.actions{display:flex;gap:6px;flex-wrap:wrap}.action{border:0;border-radius:7px;padding:7px 9px;font-size:8px;font-weight:800;cursor:pointer}.approve{background:#e8f8ef;color:#16834a}.block{background:#ffe8ec;color:#c00032}.activate{background:#eaf4ff;color:#1667a8}.reject{background:#f2f2f2;color:#666}@media(max-width:900px){.main{margin-left:0;width:100%;padding:12px}.stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><?php include __DIR__.'/admin-sidebar.php'; ?><main class="main"><header class="topbar"><div><h1>Manage Riders</h1><p>Approve, activate and manage Humsafar delivery riders.</p></div><div class="date"><i class="fa-regular fa-calendar"></i> <?=date('d M Y')?></div></header><?php if($message):?><div class="message <?=$message_type==='success'?'success':'error'?>"><?=h($message)?></div><?php endif;?><section class="banner"><div><h2>Rider Management</h2><p>Review rider applications and control rider account status.</p></div><div class="banner-icon"><i class="fa-solid fa-motorcycle"></i></div></section><section class="stats"><div class="stat"><i class="fa-solid fa-users" style="color:#ef003c"></i><strong><?=$total?></strong><span>Total Riders</span></div><div class="stat"><i class="fa-solid fa-clock" style="color:#d65bb3"></i><strong><?=$pending?></strong><span>Pending Approval</span></div><div class="stat"><i class="fa-solid fa-circle-check" style="color:#20b8d0"></i><strong><?=$active?></strong><span>Active Riders</span></div><div class="stat"><i class="fa-solid fa-user-slash" style="color:#ef003c"></i><strong><?=$inactive?></strong><span>Inactive Riders</span></div><div class="stat"><i class="fa-solid fa-ban" style="color:#ef003c"></i><strong><?=$blocked?></strong><span>Blocked Riders</span></div></section><section class="card"><div class="card-head"><i class="fa-solid fa-motorcycle" style="color:#ef003c"></i><div><h3>Rider Accounts</h3><p>View complete rider information and manage approvals.</p></div></div><form class="filter" method="get"><div class="row"><div class="search"><i class="fa-solid fa-magnifying-glass"></i><input name="search" value="<?=h($search)?>" placeholder="Search by name, email, phone, CNIC or bike number..."></div><select class="select" name="status"><option value="all" <?=$status_filter==='all'?'selected':''?>>All Riders</option><option value="pending" <?=$status_filter==='pending'?'selected':''?>>Pending</option><option value="active" <?=$status_filter==='active'?'selected':''?>>Active</option><option value="inactive" <?=$status_filter==='inactive'?'selected':''?>>Inactive</option><option value="blocked" <?=$status_filter==='blocked'?'selected':''?>>Blocked</option></select><button class="btn"><i class="fa-solid fa-filter"></i> Filter</button><a class="reset" href="manage-riders.php"><i class="fa-solid fa-rotate-left"></i>&nbsp; Reset</a></div></form><div class="table-wrap"><table><thead><tr><th>Rider</th><th>Contact</th><th>CNIC</th><th>Vehicle</th><th>Address</th><th>Status</th><th>Registered</th><th>Actions</th></tr></thead><tbody><?php if(!$riders):?><tr><td colspan="8" style="text-align:center;padding:30px;color:#999">No riders found.</td></tr><?php else:foreach($riders as $r):$status=strtolower($r['status']??'inactive');$cls=$status==='active'?'active-pill':($status==='pending'?'pending-pill':($status==='blocked'?'blocked-pill':'inactive-pill'));?><tr><td><div class="rider"><div class="avatar"><?=h(strtoupper(substr($r['full_name']??'R',0,1)))?></div><div><div class="name"><?=h($r['full_name']??'Unknown')?></div><div class="muted">Rider #<?=h($r['id'])?></div></div></div></td><td><b><?=h($r['phone']??'—')?></b><div class="muted"><?=h($r['email']??'')?></div></td><td><?=h($r['cnic']??'—')?></td><td><span class="pill" style="background:#fff0f5;color:#ef003c"><?=h($r['vehicle_type']??'—')?></span><div class="muted">Bike No: <?=h($r['bike_number']??'—')?></div></td><td><?=h($r['address']??'—')?></td><td><span class="pill <?=$cls?>"><i class="fa-solid fa-circle" style="font-size:5px"></i> <?=h(ucfirst($status))?></span></td><td><?=h($r['created_at']??'—')?></td><td><div class="actions"><?php if($status==='pending'):?><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="approve"><button class="action approve"><i class="fa-solid fa-check"></i> Approve</button></form><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="reject"><button class="action reject"><i class="fa-solid fa-xmark"></i> Reject</button></form><?php elseif($status==='active'):?><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="block"><button class="action block"><i class="fa-solid fa-ban"></i> Block</button></form><?php elseif($status==='blocked'||$status==='inactive'):?><form method="post"><input type="hidden" name="rider_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="activate"><button class="action activate"><i class="fa-solid fa-power-off"></i> Activate</button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></body></html>